188:    * Starts this service if it is not already running. This method will block until the server has
189:    * been fully started and is ready to handle commands.
190:    *
191:    * @throws IOException If an error occurs while spawning the child process.
192:    * @see #stop()
193:    */
194:   public void start() throws IOException {
195:     lock.lock();
196:     try {
197:       if (process != null) {
198:         return;
199:       }
200:       if (this.executable == null) {
201:         if (getDefaultDriverOptions().getBrowserName().isEmpty()) {
202:           throw new WebDriverException("Driver executable is null and browser name is not set.");
203:         }
204:         this.executable = new DriverFinder(this, getDefaultDriverOptions()).getDriverPath();
205:       }
206:       LOG.fine(String.format("Starting driver at %s with %s", this.executable, this.args));
207: 
208:       ExternalProcess.Builder builder =
209:           ExternalProcess.builder().command(this.executable, args).copyOutputTo(getOutputStream());
210: 
211:       environment.forEach(builder::environment);
212:       process = builder.start();
213: 
214:       CompletableFuture<StartOrDie> serverStarted =
215:           CompletableFuture.supplyAsync(
216:               () -> {
217:                 waitUntilAvailable();
218:                 return StartOrDie.SERVER_STARTED;
219:               },
220:               executorService);
221: 
222:       CompletableFuture<@Nullable StartOrDie> processFinished =
223:           CompletableFuture.supplyAsync(
224:               () -> {
225:                 try {
226:                   return process.waitFor(getTimeout())
227:                       ? StartOrDie.PROCESS_DIED
228:                       : StartOrDie.PROCESS_IS_ACTIVE;
229:                 } catch (InterruptedException ex) {
230:                   return null;
231:                 }
232:               },
233:               executorService);
234: 
235:       try {
236:         StartOrDie status =
237:             (StartOrDie)
238:                 CompletableFuture.anyOf(serverStarted, processFinished)
239:                     .get(getTimeout().toMillis() * 2, TimeUnit.MILLISECONDS);
240: 
241:         if (status == null) {
242:           throw new InterruptedException();
243:         }
244: 
245:         switch (status) {
246:           case SERVER_STARTED:
247:             processFinished.cancel(true);
248:             break;
249:           case PROCESS_DIED:
250:             int exitValue = process.exitValue();
251:             process = null;
252:             throw new WebDriverException(
253:                 "Driver server process died prematurely, exit value: " + exitValue);
254:           case PROCESS_IS_ACTIVE:
255:             process.shutdown();
256:             throw new WebDriverException("Timed out waiting for driver server to bind the port.");
257:         }
258:       } catch (ExecutionException e) {
259:         process.shutdown();
260:         throw new WebDriverException("Failed waiting for driver server to start.", e);
261:       } catch (TimeoutException e) {
262:         process.shutdown();
263:         throw new WebDriverException("Timed out waiting for driver server to start.", e);
264:       } catch (InterruptedException e) {
265:         process.shutdown();
266:         Thread.currentThread().interrupt();
267:         throw new WebDriverException("Interrupted while waiting for driver server to start.", e);
268:       }
269:     } finally {
270:       lock.unlock();
271:     }
272:   }
