290:    * Stops this service if it is currently running. This method will attempt to block until the
291:    * server has been fully shutdown.
292:    *
293:    * @see #start()
294:    */
295:   public void stop() {
296:     lock.lock();
297: 
298:     WebDriverException toThrow = null;
299:     try {
300:       if (process == null) {
301:         return;
302:       }
303: 
304:       if (hasShutdownEndpoint()) {
305:         try {
306:           URL killUrl = new URL(url.toString() + "/shutdown");
307:           new UrlChecker().waitUntilUnavailable(3, SECONDS, killUrl);
308:           try {
309:             process.waitFor(Duration.ofSeconds(10));
310:           } catch (InterruptedException e) {
311:             Thread.currentThread().interrupt();
312:           }
313:         } catch (MalformedURLException e) {
314:           toThrow = new WebDriverException(e);
315:         } catch (UrlChecker.TimeoutException e) {
316:           toThrow = new WebDriverException("Timed out waiting for driver server to shutdown.", e);
317:         }
318:       }
319: 
320:       process.shutdown();
321: 
322:       if (getOutputStream() instanceof FileOutputStream) {
323:         try {
324:           getOutputStream().close();
325:         } catch (IOException ignore) {
326:         }
327:       }
328:     } finally {
329:       process = null;
330:       lock.unlock();
331:       close();
332:     }
333: 
334:     if (toThrow != null) {
335:       throw toThrow;
336:     }
337:   }
